SELECT COUNT(*) FROM (
    SELECT upkeeprobot, 
           SUM(faultpredscore * (1.0 / (1 + COALESCE(upkeepduedays, 0)))::numeric) / SUM((1.0 / (1 + COALESCE(upkeepduedays, 0)))::numeric) as wfps
    FROM maintenance_and_fault 
    GROUP BY upkeeprobot
) sub WHERE wfps > 0.5;

SELECT COUNT(*) FROM (
    SELECT upkeeprobot, 
           SUM(faultpredscore * (1.0 / (1 + COALESCE(upkeepduedays, 0)))::numeric) / SUM((1.0 / (1 + COALESCE(upkeepduedays, 0)))::numeric) as wfps
    FROM maintenance_and_fault 
    GROUP BY upkeeprobot
) sub WHERE wfps > 0.8;
